import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var value = 0L
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

fun main() {
    val fs = FastScanner()

    val initialHp = fs.nextLong()
    val initialAtk = fs.nextLong()
    val initialDef = fs.nextLong()

    val monsterHp = fs.nextLong()
    val monsterAtk = fs.nextLong()
    val monsterDef = fs.nextLong()

    val hpCost = fs.nextLong()
    val atkCost = fs.nextLong()
    val defCost = fs.nextLong()

    var answer = Long.MAX_VALUE
    val maxAtk = maxOf(initialAtk, monsterDef + monsterHp)
    val maxDef = maxOf(initialDef, monsterAtk)

    for (atk in initialAtk..maxAtk) {
        val damageToMonster = maxOf(0L, atk - monsterDef)
        if (damageToMonster == 0L) continue

        val turns = (monsterHp + damageToMonster - 1) / damageToMonster

        for (def in initialDef..maxDef) {
            val damageToYang = maxOf(0L, monsterAtk - def)
            val requiredHp = turns * damageToYang + 1

            val totalCost =
                (atk - initialAtk) * atkCost +
                (def - initialDef) * defCost +
                maxOf(0L, requiredHp - initialHp) * hpCost

            answer = minOf(answer, totalCost)
        }
    }

    print(answer)
}

