import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value * sign
    }
}

fun main() {
    val fs = FastScanner()

    val hpY = fs.nextInt()
    val atkY = fs.nextInt()
    val defY = fs.nextInt()

    val hpM = fs.nextInt()
    val atkM = fs.nextInt()
    val defM = fs.nextInt()

    val hpCost = fs.nextInt()
    val atkCost = fs.nextInt()
    val defCost = fs.nextInt()

    var answer = Long.MAX_VALUE
    val maxAttack = maxOf(atkY, defM + hpM)
    val maxDefense = maxOf(defY, atkM)

    for (attack in atkY..maxAttack) {
        val damageToMonster = attack - defM
        if (damageToMonster <= 0) continue

        val turns = (hpM + damageToMonster - 1) / damageToMonster

        for (defense in defY..maxDefense) {
            val damageToYang = maxOf(0, atkM - defense)
            val requiredHp = turns * damageToYang + 1
            val extraHp = maxOf(0, requiredHp - hpY)

            val cost =
                extraHp.toLong() * hpCost +
                (attack - atkY).toLong() * atkCost +
                (defense - defY).toLong() * defCost

            answer = minOf(answer, cost)
        }
    }

    println(answer)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.max
import kotlin.math.min

private class FastScanner {
    private val reader = BufferedReader(InputStreamReader(System.`in`))
    private var tokenizer = StringTokenizer("")

    fun nextLong(): Long {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = StringTokenizer(reader.readLine())
        }
        return tokenizer.nextToken().toLong()
    }
}

fun main() {
    val fs = FastScanner()

    val hpY = fs.nextLong()
    val atkY = fs.nextLong()
    val defY = fs.nextLong()

    val hpM = fs.nextLong()
    val atkM = fs.nextLong()
    val defM = fs.nextLong()

    val hpCost = fs.nextLong()
    val atkCost = fs.nextLong()
    val defCost = fs.nextLong()

    var answer = Long.MAX_VALUE
    val maxAtk = defM + hpM
    val maxDef = max(defY, atkM)

    for (atk in atkY..max(atkY, maxAtk)) {
        val damageToMonster = max(1L, atk - defM)
        val turns = (hpM + damageToMonster - 1) / damageToMonster

        for (def in defY..maxDef) {
            val damageToYang = max(0L, atkM - def)
            val requiredHp = turns * damageToYang + 1
            val hpToBuy = max(0L, requiredHp - hpY)

            val totalCost =
                hpToBuy * hpCost +
                (atk - atkY) * atkCost +
                (def - defY) * defCost

            answer = min(answer, totalCost)
        }
    }

    println(answer)
}
